<?php
declare(strict_types=1);
require_once __DIR__ . '/auth.php';
require_once __DIR__ . '/db.php';
require_role('employee');
$pdo = db();
$userId = (int) $_SESSION['user']['id'];
$stmt = $pdo->prepare('SELECT c.id, c.name, c.industry FROM clients c INNER JOIN client_employees ce ON ce.client_id = c.id WHERE ce.employee_id = ? AND c.active = 1 ORDER BY c.name');
$stmt->execute([$userId]); $clients = $stmt->fetchAll();
$stmt = $pdo->prepare("SELECT c.id content_id, c.title, c.status, c.content_type, cl.name client_name FROM content c INNER JOIN clients cl ON cl.id = c.client_id INNER JOIN client_employees ce ON ce.client_id = c.client_id WHERE ce.employee_id = ? ORDER BY c.updated_at DESC LIMIT 20");
$stmt->execute([$userId]); $content = $stmt->fetchAll();
$stmt = $pdo->prepare("SELECT t.id, t.title, t.due_date, t.status, c.name client_name FROM tasks t INNER JOIN clients c ON c.id = t.client_id WHERE t.assigned_to = ? AND t.due_date < CURDATE() AND t.status <> 'completed' ORDER BY t.due_date");
$stmt->execute([$userId]); $overdueTasks = $stmt->fetchAll();
$pending = count(array_filter($content, fn($x) => $x['status'] === 'pending'));
$changes = count(array_filter($content, fn($x) => $x['status'] === 'changes_requested'));
function e(string $v): string { return htmlspecialchars($v, ENT_QUOTES, 'UTF-8'); }
?>
<script src="assets/js/responsive-nav.js?v=2" defer></script>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Employee Dashboard</title><link rel="stylesheet" href="assets/css/saas.css"></head><body class="saas-body"><div class="saas-shell"><aside class="saas-sidebar"><div class="brand"><span>MT</span> Mega Techzy</div><div class="nav-label">Workspace</div><a class="saas-nav active" href="employee_dashboard.php">▦ <span>Overview</span></a><a class="saas-nav" href="my_tasks.php">✓ <span>My tasks</span></a><a class="saas-nav" href="upload_content.php">↑ <span>Upload content</span></a><a class="saas-nav" href="employee_clients.php">♙ <span>Client profiles</span></a><div class="nav-label">Account</div><a class="saas-nav" href="my_payslip.php">▤ <span>My payslips</span></a><a class="saas-nav" href="apply_leave.php">◷ <span>Leave</span></a><a class="saas-nav" href="activity_log.php">◌ <span>Activity</span></a><a class="saas-nav" href="logout.php">↪ <span>Log out</span></a></aside><main class="saas-main"><header class="saas-topbar"><div><h1 class="saas-title">My workspace</h1><div class="saas-subtitle">Manage assigned clients and content approvals.</div></div><div class="saas-toolbar"><div class="avatar"><?= e(strtoupper(substr($_SESSION['user']['name'], 0, 1))) ?></div></div></header><section class="kpi-grid"><div class="kpi-card"><div class="kpi-icon">♙</div><div class="kpi-label">Assigned clients</div><div class="kpi-value"><?= count($clients) ?></div><div class="trend muted">Active accounts</div></div><div class="kpi-card amber"><div class="kpi-icon amber">◷</div><div class="kpi-label">Pending review</div><div class="kpi-value"><?= $pending ?></div><div class="trend muted">Awaiting client response</div></div><div class="kpi-card expense"><div class="kpi-icon red">!</div><div class="kpi-label">Changes requested</div><div class="kpi-value"><?= $changes ?></div><div class="trend muted">Needs attention</div></div><div class="kpi-card expense"><div class="kpi-icon red">!</div><div class="kpi-label">Overdue tasks</div><div class="kpi-value"><?= count($overdueTasks) ?></div><div class="trend muted">Not completed by due date</div></div></section><?php if ($overdueTasks): ?><section class="saas-card" style="margin-bottom:16px;border-left:4px solid #ef4444"><h2 class="text-danger">Overdue tasks</h2><div class="table-responsive"><table class="saas-table"><thead><tr><th>Task</th><th>Client</th><th>Due</th><th>Status</th></tr></thead><tbody><?php foreach ($overdueTasks as $task): ?><tr><td><?= e($task['title']) ?></td><td><?= e($task['client_name']) ?></td><td class="text-danger fw-semibold"><?= e($task['due_date']) ?></td><td><?= e(ucwords(str_replace('_', ' ', $task['status']))) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?><section class="saas-card" style="margin-bottom:16px"><div class="saas-topbar" style="margin-bottom:10px"><h2>Assigned clients</h2><a class="btn-indigo" href="upload_content.php">Upload content</a></div><?php if (!$clients): ?><div class="empty-state"><span class="empty-icon">♙</span>No clients assigned yet.</div><?php else: ?><div style="overflow:auto"><table class="saas-table"><thead><tr><th>Client</th><th>Industry</th><th>Actions</th></tr></thead><tbody><?php foreach ($clients as $client): ?><tr><td><strong><?= e($client['name']) ?></strong></td><td><?= e($client['industry'] ?? '') ?></td><td><a class="btn-outline-indigo" href="view_client_profile.php?client_id=<?= $client['id'] ?>">Profile</a> <a class="btn-indigo" href="upload_content.php?client_id=<?= $client['id'] ?>">Upload</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><section class="saas-card"><h2>Recent content</h2><?php if (!$content): ?><div class="empty-state"><span class="empty-icon">◌</span>No content uploaded yet.</div><?php else: ?><div style="overflow:auto"><table class="saas-table"><thead><tr><th>Client</th><th>Content</th><th>Type</th><th>Status</th></tr></thead><tbody><?php foreach ($content as $item): ?><tr><td><?= e($item['client_name']) ?></td><td><a href="approve_content.php?content_id=<?= $item['content_id'] ?>"><?= e($item['title']) ?></a></td><td><?= e(ucfirst($item['content_type'])) ?></td><td><span class="status-pill status-<?= e($item['status']) ?>"><?= e(ucwords(str_replace('_', ' ', $item['status']))) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></main></div></body></html>
